        'guide.wizard.welcome.title': 'Bem-vindo ao Actor Empire',
        'guide.wizard.welcome.body': 'Você está construindo uma vida, não só correndo atrás de um papel. Os melhores saves equilibram carreira, dinheiro, fama, relacionamentos, poder de estúdio e planejamento.',
        'guide.wizard.weeklyLoop.title': 'Seu Loop Semanal',
        'guide.wizard.weeklyLoop.body': 'Cada semana é um quebra-cabeça de recursos. Gaste energia em atuação, crescimento social, negócios ou vida pessoal, depois avance a idade para ver os resultados.',
        'guide.wizard.career.title': 'Construa a Carreira Primeiro',
        'guide.wizard.career.body': 'CastLink, ensaios, agentes melhores e boas performances abrem a escada do entretenimento. No começo, trabalho constante e escolhas inteligentes importam mais que só perseguir projetos gigantes.',
        'guide.wizard.stats.title': 'Entenda Cada Stat',
        'guide.wizard.stats.body': 'Fama aumenta seu perfil. Reputação melhora confiança. Seguidores aumentam alcance. Dinheiro dá opções. Nenhum deles substitui totalmente os outros.',
        'guide.wizard.business.title': 'Negócios Precisam de Gestão',
        'guide.wizard.business.body': 'Negócios não imprimem dinheiro sozinhos. Preço, hype, equipe, estoque e expansão importam.',
        'guide.wizard.studio.title': 'Produtora é Jogo Longo',
        'guide.wizard.studio.body': 'Seu estúdio brilha quando você desenvolve bons projetos, gerencia lançamentos e transforma vitórias em catálogo. Grandes retornos podem levar tempo.',
        'guide.wizard.stories.title': 'Histórias Conectadas Precisam de Cuidado',
        'guide.wizard.stories.body': 'Franquias e universos são fortes porque personagens, elenco, sequências, crossovers e memória de mercado continuam avançando.',
        'guide.handbook.title': 'Manual',
        'guide.handbook.subtitle': 'Uma referência simples sobre como o jogo funciona, para que serve cada sistema e quando se importar com ele.',
        'guide.handbook.gettingStarted.title': 'Começando',
        'guide.handbook.gettingStarted.p1': 'Seu primeiro objetivo é criar impulso confiável. Pequenas vitórias em audições, atividade social e gestão de dinheiro costumam vencer apostas arriscadas no início.',
        'guide.handbook.gettingStarted.p2': 'Pense semana a semana. Toda decisão compete por tempo e energia, e se espalhar demais desacelera tudo.',
        'guide.handbook.gettingStarted.p3': 'Use os apps do celular com frequência. CastLink cresce sua carreira, Team cuida de contratos, apps sociais ampliam alcance e o Guia explica o resto.',
        'guide.handbook.stats.title': 'Stats Explicados',
        'guide.handbook.stats.p1': 'Fama é seu perfil público. Ajuda você a ser visto, conseguir oportunidades maiores e continuar relevante.',
        'guide.handbook.stats.p2': 'Reputação é o quanto a indústria leva você a sério. Alta reputação apoia confiança e melhores resultados de longo prazo.',
        'guide.handbook.stats.p3': 'Seguidores são seu alcance social. Ajudam influência, patrocínios e crescimento online, mas não carregam uma carreira de atuação sozinhos.',
        'guide.handbook.stats.p4': 'Humor e energia moldam o quanto você consegue fazer. Uma conta rica vale menos se o personagem está exausto ou infeliz.',
        'guide.handbook.career.title': 'Fluxo de Carreira',
        'guide.handbook.career.p1': 'CastLink é o principal lugar para encontrar trabalho. Talento, preparo, experiência e representação melhores aumentam a qualidade dos papéis.',
        'guide.handbook.career.p2': 'Preparo importa. Ensaios e boas escolhas de papel tornam performances mais consistentes.',
        'guide.handbook.career.p3': 'O começo constrói histórico, o meio constrói impulso e o fim é sobre poder de escolha, negociação e legado.',
        'guide.handbook.weeklyLoop.title': 'Loop Semanal e Energia',
        'guide.handbook.weeklyLoop.p1': 'Energia é o combustível semanal. Atuação, ações sociais, trabalho em negócios e vida pessoal usam esse recurso.',
        'guide.handbook.weeklyLoop.p2': 'Não desperdice semanas vazias. Se estiver esperando um projeto, construa fama, relações, habilidades ou progresso nos negócios.',
        'guide.handbook.weeklyLoop.p3': 'Recuperação tem valor. Às vezes restaurar o personagem deixa as próximas semanas mais fortes.',
        'guide.handbook.social.title': 'Fama, Seguidores e Social',
        'guide.handbook.social.p1': 'Redes sociais mantêm você visível e podem apoiar a carreira de entretenimento.',
        'guide.handbook.social.p2': 'Plataformas diferentes fazem trabalhos diferentes: imagem, alcance, conversa e monetização.',
        'guide.handbook.social.p3': 'Use social com propósito. Nem todo post precisa tentar viralizar.',
        'guide.handbook.relationships.title': 'Relacionamentos e Networking',
        'guide.handbook.relationships.p1': 'Relacionamentos profissionais podem mudar a qualidade das oportunidades que você vê.',
        'guide.handbook.relationships.p2': 'Relacionamentos pessoais não são só detalhe. Negligência cria drama, enquanto vínculos saudáveis apoiam uma vida melhor.',
        'guide.handbook.relationships.p3': 'Networking funciona melhor com tempo. Esforço repetido costuma vencer um gesto caro isolado.',
        'guide.handbook.businesses.title': 'Negócios',
        'guide.handbook.businesses.p1': 'Negócios são motores de renda de longo prazo. Alguns são serviços estáveis, enquanto negócios de produto recompensam gestão ativa.',
        'guide.handbook.businesses.p2': 'Preço, qualidade, hype, equipe, estoque e expansão importam.',
        'guide.handbook.businesses.p3': 'Marketing funciona melhor quando produto, capacidade e estrutura já estão saudáveis.',
        'guide.handbook.productionHouse.title': 'Produtora',
        'guide.handbook.productionHouse.p1': 'Pense em etapas: desenvolvimento, produção, lançamento e vida posterior importam.',
        'guide.handbook.productionHouse.p2': 'Nem todo projeto deve ser apressado. Planejamento forte pode vencer lançar tudo rápido demais.',
        'guide.handbook.productionHouse.p3': 'Seu catálogo importa. Com o tempo, o estúdio vale mais quando você constrói biblioteca em vez de depender de um único hit.',
        'guide.handbook.developmentLab.title': 'Lab de Desenvolvimento',
