        'guide.handbook.scriptFormats.title': 'Roteiros, Gêneros e Formatos',
        'guide.handbook.scriptFormats.p1': 'Formato é a forma de produção, como filme, série, live action, animação ou anime.',
        'guide.handbook.scriptFormats.p2': 'Gênero é a promessa ao público, como drama, ação, biopic, esportes, documentário, musical, animação, anime e similares.',
        'guide.handbook.scriptFormats.p3': 'Gênero principal carrega a identidade. Gênero secundário adiciona sabor e deve apoiar o projeto.',
        'guide.handbook.scriptFormats.tag1': 'Formato = pacote',
        'guide.handbook.scriptFormats.tag2': 'Gênero = promessa',
