        'guide.handbook.greenlight.title': 'Fluxo de Greenlight',
        'guide.handbook.greenlight.p1': 'Greenlight transforma um roteiro em plano de produção com diretor, elenco, equipe, equipamentos, locações, tom e pacote final.',
        'guide.handbook.greenlight.p2': 'Orçamento não é só número. Cachês, qualidade da equipe, escolhas de produção, personagens conhecidos e escala mudam tudo.',
        'guide.handbook.greenlight.p3': 'Negociação importa. Elenco retornando e nomes maiores podem ser fortes, mas ainda precisam fechar acordos.',
        'guide.handbook.greenlight.b1': 'Use a etapa de elenco para travar quem interpreta cada papel.',
        'guide.handbook.greenlight.b2': 'Use personagens conectados quando a história pertence a uma franquia ou universo.',
        'guide.handbook.greenlight.b3': 'Use a revisão para encontrar pontos fracos antes de confirmar.',
