        'app.whatsNew.version': 'Versão {version}',
        'app.whatsNew.intro': 'Vá além da atuação nesta atualização: compre estúdios, dispute direitos, lance projetos maiores, ganhe recompensas premium e transforme sua carreira em um império do entretenimento.',
        'app.whatsNew.studioStreaming': 'Império de Estúdios',
        'app.whatsNew.studioStreaming.1': '• Compre estúdios, crie um grupo de estúdios e evolua de ator para dono com progressão de negócios mais forte.',
        'app.whatsNew.studioStreaming.2': '• Aquisições de estúdio agora incluem respostas do vendedor, interesse rival, assinatura, pressão de dívida e transferência de propriedade.',
        'app.whatsNew.studioStreaming.3': '• Operações de subsidiárias, mandatos, decisões e repasses de produção deixam estúdios próprios mais vivos.',
        'app.whatsNew.careerFamily': 'Direitos, Lançamentos e Bilheteria',
        'app.whatsNew.careerFamily.1': '• Descubra direitos, investigue IPs, negocie ofertas e transforme propriedades valiosas em novos projetos.',
        'app.whatsNew.careerFamily.2': '• Greenlight, marketing, distribuição e planejamento de lançamento agora trazem decisões mais claras antes da estreia.',
        'app.whatsNew.careerFamily.3': '• Histórico de bilheteria, recordes, gráficos semanais, regiões e redes de cinema deixam cada lançamento mais fácil de acompanhar.',
        'app.whatsNew.mobileStability': 'Prêmios, Celular e Estilo de Vida',
        'app.whatsNew.mobileStability.1': '• Noite de premiação, recordes de carreira, Forbes, IMDb, YouTube, X, mensagens e apps do celular agora mostram feedback mais rico.',
        'app.whatsNew.mobileStability.2': '• Bens de estilo de vida, casas, veículos, roupas e coleções dão mais formas de mostrar o sucesso da sua estrela.',
        'app.whatsNew.mobileStability.3': '• Recompensas da loja agora suportam Sem Anúncios, pacotes de energia, boosts de dinheiro e bundles premium no mobile.',
        'app.whatsNew.uiSaveFixes': 'Ajuda para Novos Jogadores e Polimento',
        'app.whatsNew.uiSaveFixes.1': '• Um novo tutorial dentro do jogo ajuda carreiras novas a entenderem o ciclo principal mais rápido.',
        'app.whatsNew.uiSaveFixes.2': '• Balanceamento de energia, proteção de saves antigos, estabilidade em carreiras longas e recuperação foram reforçados.',
        'app.whatsNew.uiSaveFixes.3': '• Limpeza de UI em festivais, carreira, social/notícias, produção e finanças deixa telas avançadas mais fáceis de ler.',
        'app.whatsNew.previousNotes': 'Também Incluído',
        'app.whatsNew.previousNotesSubtext': 'Toque para ver correções de estabilidade, relacionamento e talentos retornando incluídas nesta versão.',
        'app.whatsNew.previousHighlights': 'Correções e Estabilidade',
        'app.whatsNew.previousHighlights.1': '• Crescimento de streaming, disputas de ofertas, sequências/temporadas e bloqueios de talentos retornando foram corrigidos.',
        'app.whatsNew.previousHighlights.2': '• Gravidez, relacionamentos, feedback de bebê e romances entre pessoas do mesmo sexo/não binárias agora se comportam melhor.',
        'app.whatsNew.previousHighlights.3': '• Armazenamento de saves, recuperação de timelines antigas, overflow decimal e loops semanais travados receberam proteção extra.',
