        'services.news.forbes.industry.headline': 'Forbes divulga relatório anual sobre fortuna no cinema.',
        'services.news.universe.background.headline': 'Fãs especulam intensamente sobre a próxima fase do universo {universeName}.',
        'services.news.industry.trend': 'Executivos de estúdio veem sinais de cansaço com franquias entre o público jovem. || A guerra do streaming esquenta com plataformas disputando direitos exclusivos. || Críticos dizem que a era da estrela de cinema está voltando. || Estúdios migram discretamente para thrillers de orçamento médio. || Receita de produtos licenciados vira fator decisivo para aprovar sequências.',
        'services.news.industry.npc': '{name} deve estrelar uma nova cinebiografia. || {name} deixa projeto por diferenças criativas. || Rumores crescem sobre {name} em uma franquia de super-heróis. || {name} vira assunto de prêmios após exibição privada. || {name} se torna alvo de forte especulação sobre recast.',
        'services.news.release.hit.headline': "'{title}' domina as bilheterias pela segunda semana. || O público lota sessões de '{title}' e surpreende analistas. || '{title}' vira fenômeno cultural. || '{title}' transforma bom buzz em força real de bilheteria. || '{title}' parece o sucesso que os estúdios esperavam.",
        'services.news.release.hit.universeHeadline': "'{title}' prova que o universo cinematográfico está mais forte do que nunca. || Fãs chamam '{title}' de melhor entrada da franquia até agora. || Bilheteria explode enquanto '{title}' expande a mitologia do universo. || '{title}' prepara perfeitamente o próximo grande crossover.",
        'services.news.release.flop.headline': "'{title}' tropeça na estreia com abertura fraca. || Preocupações de orçamento cercam '{title}' após desempenho abaixo do esperado. || Erro de marketing é apontado no desempenho decepcionante de '{title}'. || Indiferença do público deixa '{title}' em território perigoso. || O otimismo do estúdio cai enquanto '{title}' não decola.",
        'services.news.release.flop.universeHeadline': "Cansaço de franquia? '{title}' fica abaixo do esperado. || '{title}' não captura a magia das entradas anteriores do universo. || Fãs se decepcionam com '{title}' e questionam a direção do universo. || Um raro tropeço da franquia: '{title}' fracassa nas bilheterias.",
        'services.news.release.criticLoved.headline': "Críticos chamam '{title}' de obra-prima moderna. || '{title}' gera burburinho inicial de Oscar. || '{title}' vira o queridinho da crítica na temporada. || Resenhistas dizem que '{title}' supera expectativas em quase tudo.",
        'services.news.release.criticLoved.universeHeadline': "Críticos elogiam '{title}' por elevar toda a franquia. || '{title}' prova que filmes de super-herói podem buscar arte maior. || A construção de mundo de '{title}' impressiona críticos. || '{title}' equilibra serviço aos fãs com uma história forte.",
        'services.news.release.criticHated.headline': "Críticos detonam '{title}' por roteiro fraco. || '{title}' é chamado de confusão por grandes resenhistas. || Estilo acima de substância: '{title}' não convence. || '{title}' é chamado de superproduzido, mal escrito e esquecível.",
        'services.news.release.criticHated.universeHeadline': "Críticos veem '{title}' como produto sem alma. || '{title}' depende demais de cameos e esquece a trama. || Excesso de lore em '{title}' afasta espectadores casuais. || Resenhas dizem que '{title}' mostra um universo perdendo rumo.",
        'services.news.sequel.hype.headline': "Fãs pedem sequência de '{title}' nas redes. || O buzz cresce em torno de um possível universo de '{title}'. || O público quer ver mais do mundo de '{title}'. || Especulação cresce sobre uma continuação de '{title}'. || Analistas dizem que '{title}' tem perfil claro para virar série.",
        'services.news.sequel.confirmed.headline': "É OFICIAL: estúdio aprova sequência de '{title}'. || '{title} 2' vai acontecer! Pré-produção começa em breve. || Estúdio confirma retorno ao mundo de '{title}'. || Alerta de franquia: sequência de '{title}' é anunciada oficialmente.",
        'services.news.scandal.headline': 'URGENTE: {name} entra em nova controvérsia. || É o fim para {name}? Novas acusações surgem. || Redes sociais explodem após o passado de {name} voltar à tona. || Opinião pública sobre {name} despenca. || Equipe de {name} corre para conter uma crise de PR.',
        'services.news.legal.headline': 'Batalha legal se aproxima para {name} com data no tribunal marcada. || Por dentro do tribunal: o drama jurídico de {name}. || {name} vai fechar acordo? Especialistas analisam o caso. || Problemas legais aumentam a pressão sobre a carreira de {name}. || Equipe jurídica de {name} sinaliza uma defesa agressiva.',
