        'services.npcVenture.launch.headline': '{Owner} lança {Venture}, uma nova {Archetype} com ambições sérias na indústria. || Novo jogador: {Venture}, apoiada por {Owner}, entra na corrida de produção. || {Venture} abre as portas enquanto {Owner} aposta mais em propriedade. || Radar da indústria: {Owner} constrói discretamente {Venture} como novo veículo em Hollywood.',
        'services.npcVenture.launch.subtext': '{ventureName} começa com cerca de ${capital}M em capital de lançamento.',
        'services.npcVenture.development.headline': '{Venture} está empacotando {Title}, e insiders chamam de aposta calculada. || {Venture} começa o desenvolvimento de {Title} enquanto rivais observam de perto. || A {Venture} de {Owner} começa a buscar talentos para {Title}. || Conversas de disputa crescem em torno de {Title}, o movimento mais recente de {Venture}.',
        'services.npcVenture.development.subtext': '{ventureName} ainda está construindo seu slate.',
        'services.npcVenture.hit.headline': '{Venture} emplaca um grande sucesso com {Title}. || {Title} transforma {Venture} de projeto de vaidade em concorrente real. || Surpresa da indústria: {Venture} conquista uma vitória importante com {Title}. || A aposta de propriedade de {Owner} dá certo quando {Title} supera expectativas.',
        'services.npcVenture.hit.subtext': 'Estrelado por {leadActorName}. Dirigido por {directorName}.',
        'services.npcVenture.flop.headline': '{Venture} sofre um golpe caro depois que {Title} fica abaixo do esperado. || {Title} tropeça e coloca pressão na {Venture} de {Owner}. || Semana difícil: {Venture} enfrenta perguntas após {Title} decepcionar. || Insiders se perguntam se {Venture} avançou rápido demais depois do fracasso de {Title}.',
        'services.npcVenture.flop.subtext': 'O erro afetou as reservas de caixa de {ventureName}.',
        'services.npcVenture.closure.headline': '{Venture} fecha após uma sequência difícil de projetos. || {Owner} fecha {Venture} enquanto as perdas aumentam. || Fim da linha: {Venture} encerra operações discretamente. || {Venture} sai do mercado após não criar impulso sustentável.',
        'services.npcVenture.closure.reason.cash': 'As reservas de caixa colapsaram.',
        'services.npcVenture.closure.reason.slate': 'O slate não conseguiu tração.',
        'services.npcVenture.log.launch': '{ownerName} lançou {ventureName}.',
        'services.npcVenture.log.closure': '{ventureName} fechou após {count} lançamentos.',
        'services.npcVenture.log.offer': '📩 {ventureName} enviou uma oferta de papel.',
