        'services.npcVenture.project.type.series': 'série',
        'services.npcVenture.project.description': '{ventureName} está produzindo um projeto de {genre} em formato {projectType}, apoiado por {ownerName}.',
        'services.npcVenture.offer.intro': 'Estamos montando um pacote focado e achamos que você combina com o papel. || É um projeto mais enxuto, mas a equipe acredita que pode viajar. || Nosso estúdio está se movendo rápido e quer você anexado antes da cidade perceber. || Estamos montando o próximo slate em torno de talentos em alta, e seu nome apareceu.',
        'services.npcVenture.offer.text': '{intro}\n\nProjeto: {projectName}\nEstúdio: {studioName}\nFundador: {founderName}\nPapel: {roleType}\nPagamento estimado: ${estimatedPay}\n\nEsta é uma empresa real no mercado agora. Se o projeto acertar, o estúdio ganha momentum. Se errar, o risco fica com eles.',
