        'services.role.rejection.reason.castingPressure': 'Pressão de casting: a sala gostou de partes do seu perfil, mas não o suficiente para fechar.',
        'services.role.rejection.reason.saferFit': 'O casting queria um encaixe mais seguro para este projeto.',
        'services.role.rejection.hint.genre': 'Construa reputação em {genre} com trabalhos menores, depois busque papéis maiores nessa faixa.',
        'services.role.rejection.hint.fame': 'Acumule papéis menores, alcance social e impulso de imprensa para fazer estúdios maiores se sentirem mais seguros.',
        'services.role.rejection.hint.prep': 'Mantenha a preparação de audição alta e continue ativo; chamadas quase fechadas podem virar ofertas conforme seu trabalho recente melhora.',
        'services.role.rejection.summary.application': 'A equipe decidiu não avançar antes dos callbacks.',
        'services.role.rejection.summary.audition': 'A sala gostou de partes da sua leitura, mas o papel seguiu outro caminho.',
        'services.role.rejection.review.intro.application': 'Obrigado por se candidatar a {projectName}.',
        'services.role.rejection.review.intro.audition': 'Obrigado por vir ler para {projectName}.',
        'services.role.rejection.review.directorNote': 'Nota do diretor:\n{reason}',
        'services.role.rejection.review.castingNote': 'Nota do casting:\n{reason}',
