        'services.role.review.author': 'Crítico {index}',
        'services.role.review.publication': 'The Daily Review',
        'services.role.review.subjectPhrase.biopic': ' de {subjectName}',
        'services.role.review.subjectStory.named': 'A história de {subjectName}',
        'services.role.review.subjectStory.default': 'O tema',
        'services.role.review.positive.general': 'Uma entrada impressionante no gênero {genre}. {playerName} brilha. || Confiante, polido e movido por uma forte atuação central de {playerName}. || A técnica se sustenta, e os melhores momentos parecem genuinamente cinematográficos. || Um filme popular com coração suficiente para sobreviver além da estreia.',
        'services.role.review.mixed.general': 'Tem seus momentos, mas falha na aterrissagem. || Há peças fortes aqui, mas o filme nunca vira totalmente o evento que quer ser. || A ambição é visível, mesmo quando a execução cambaleia. || Há um bom filme dentro disso, mas precisava de estrutura mais afiada.',
        'services.role.review.negative.general': 'Uma bagunça decepcionante. Evite. || Barulhento demais, raso demais e longe de ser tão memorável quanto o orçamento sugere. || O espetáculo é caro, mas o drama parece malcozido. || Um pacote brilhante com muito pouco poder de permanência.',
        'services.role.review.thinCast': 'Para um filme tão grande, o mundo parece estranhamente vazio ao redor dos protagonistas. || A dupla principal funciona, mas a falta de ensemble faz a escala parecer menor que o orçamento. || Um elenco de apoio mais forte poderia ter feito isto parecer um evento real.',
        'services.role.review.positive.MUSICAL': 'As canções realmente carregam a história, e {playerName} dá pulso ao musical. || Coreografia, vocais e arco emocional finalmente se movem como um só.',
        'services.role.review.positive.BIOPIC': '{playerName} encontra a pessoa por baixo do mito público{subjectPhrase}. || Uma cinebiografia cuidadosa ancorada por transformação, não imitação.',
        'services.role.review.positive.SPORTS': 'As cenas esportivas têm impacto porque as apostas emocionais são claras. || Uma história sincera de azarão que deixa {playerName} mostrar garra sem perder vulnerabilidade.',
        'services.role.review.positive.DOCUMENTARY': '{subjectStory} é tratado com acesso, tensão e curiosidade real. || O documentário ganha urgência ao fazer perguntas difíceis em vez de vender respostas fáceis.',
        'services.role.review.positive.MYSTERY': 'O mistério funciona porque as pistas parecem plantadas, não trapaceadas. || Um mistério bem tensionado que deixa {playerName} jogar suspeita, contenção e descoberta.',
        'services.role.review.positive.ANIMATION': 'A animação tem personalidade, não só polimento. || Um filme animado visualmente caloroso com uma atuação de {playerName} que ainda aparece através da técnica.',
        'services.role.review.positive.CRIME': 'A trama criminal é firme, moralmente incômoda e construída com impulso real. || Uma história criminal afiada que entende consequência tanto quanto suspense.',
        'services.role.review.positive.FANTASY': 'O mundo de fantasia parece vivido, e a mitologia sustenta a emoção em vez de enterrá-la. || Uma fantasia ricamente construída que dá ao espetáculo um centro humano.',
        'services.role.review.mixed.MUSICAL': 'Os números são grudentos, mas as cenas entre eles são irregulares.',
        'services.role.review.mixed.BIOPIC': 'A atuação é comprometida, embora a cinebiografia suavize demais as verdades mais bagunçadas.',
        'services.role.review.mixed.SPORTS': 'O drama esportivo é sincero, mas muitos beats parecem familiares.',
        'services.role.review.mixed.DOCUMENTARY': 'O acesso é valioso, mas o argumento poderia ser mais afiado.',
        'services.role.review.mixed.MYSTERY': 'As pistas são intrigantes, mas a revelação final chega mais fraca que a preparação.',
        'services.role.review.mixed.ANIMATION': 'A identidade visual é forte, mesmo quando a história parece fina.',
        'services.role.review.mixed.CRIME': 'A mecânica criminal funciona, mas os personagens precisavam de mais vida interior.',
        'services.role.review.mixed.FANTASY': 'O mundo é imaginativo, mas a mitologia às vezes sufoca o drama.',
        'services.role.review.negative.MUSICAL': 'As canções travam o filme em vez de elevá-lo.',
        'services.role.review.negative.BIOPIC': 'Uma cinebiografia superficial que confunde maquiagem com insight.',
        'services.role.review.negative.SPORTS': 'As cenas esportivas carecem de autenticidade, e o drama nunca encontra segunda marcha.',
        'services.role.review.negative.DOCUMENTARY': 'O documentário tem um tema, mas não um ponto de vista.',
        'services.role.review.negative.MYSTERY': 'Um mistério com suspeitos, mas sem real senso de descoberta.',
        'services.role.review.negative.ANIMATION': 'A animação é movimentada, mas falta desenho emocional.',
        'services.role.review.negative.CRIME': 'Uma história criminal com viradas, mas sem tensão.',
        'services.role.review.negative.FANTASY': 'O mundo de fantasia é caro, confuso e estranhamente sem peso.',
        'services.role.review.positive.ANIME': 'O estilo anime traz emoção cinética e um ritmo visual distinto. || Um longa anime forte que entende fandom sem bajulá-lo.',
        'services.role.review.mixed.ANIME': 'A técnica anime é empolgante, embora o ritmo às vezes engula o trabalho de personagem.',
        'services.role.review.negative.ANIME': 'A influência anime é visível, mas o filme nunca conquista sua intensidade.',
        'services.role.review.recast.positive': 'O novo elenco injeta vida nova na franquia. Uma entrada impressionante no gênero {genre}.',
        'services.role.review.recast.mixed': 'A troca de elenco é estranha, mas tem seus momentos.',
        'services.role.review.recast.negative': 'Uma troca de elenco desastrosa arruina qualquer magia que o original tinha. Evite.',
